return [{ json: { html: "<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>Denoro · Tu monitor de precios</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
<style>:root{--bg:#fcfcfa;--surface:#fff;--surface-2:#f4f3ef;--ink:#191713;--text:#35322c;--muted:#6e6a61;--line:#e7e4dc;--line-strong:#d8d4c9;--line-field:#8f8a7e;--accent:#235b54;--accent-ink:#fff;--accent-soft:#e8efec;--accent-deep:#1a4640;--ok:#2c5f3c;--ok-soft:#e9f0ea;--bad:#8f2f24;--bad-soft:#f8eae7;--warn:#7a5a1c;--warn-soft:#f4eee1;--r-s:6px;--r-m:10px;--shadow:0 0 0 1px var(--line)}
/* Sin modo oscuro: la web de Denoro es siempre clara y el panel debe verse igual. */
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--text);font:15px/1.6 "IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif}
.mono,.num{font-family:"IBM Plex Mono",ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums}
a{color:var(--accent)}
.wrap{max-width:1080px;margin:0 auto;padding:0 20px}
header.top{background:var(--surface);border-bottom:1px solid var(--line)}
header.top .wrap{display:flex;align-items:center;gap:16px;min-height:64px;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:10px;font-weight:600;color:var(--ink);letter-spacing:-.01em}
.brand i{width:28px;height:28px;border-radius:var(--r-s);background:var(--accent);display:grid;place-items:center;color:#fff;font-style:normal;font-size:15px;font-weight:600;font-family:"Instrument Serif",serif}
.brand small{font-weight:400;color:var(--muted);font-size:13px}
.spacer{flex:1}
h1{font-family:"Instrument Serif","Iowan Old Style",Georgia,serif;font-weight:400;font-size:30px;line-height:1.2;margin:0;color:var(--ink);letter-spacing:-.02em}
h2{font-size:17px;margin:0 0 4px;color:var(--ink);font-weight:600}
p.sub{margin:4px 0 0;color:var(--muted)}
main{padding:36px 0 64px}
.grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;align-items:start}
@media (max-width:900px){.grid{grid-template-columns:1fr}}
.card{background:var(--surface);border-radius:var(--r-m);box-shadow:var(--shadow);padding:20px}
.card+.card{margin-top:20px}
.card-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px;flex-wrap:wrap}
.hint{color:var(--muted);font-size:13px}
label{display:block;font-size:13px;font-weight:500;color:var(--ink);margin:0 0 6px}
input,select{width:100%;font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--line-field);border-radius:var(--r-s);padding:10px 12px;min-height:44px}
input:focus,select:focus,button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.field{margin-bottom:14px}
.row{display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap}.row>*{flex:1 1 160px}
button,.btn{font:inherit;font-weight:500;border-radius:var(--r-s);min-height:44px;padding:0 16px;cursor:pointer;border:1px solid var(--line-field);background:var(--surface);color:var(--ink);display:inline-flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap}
button.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
button.ghost{border-color:transparent;background:transparent;color:var(--muted)}
button.danger{color:var(--bad)}
button:disabled{opacity:.55;cursor:progress}
.add{display:flex;gap:10px}.add input{flex:1}
@media (max-width:560px){.add{flex-direction:column}}
.toggle{display:flex;align-items:center;gap:10px;min-height:40px;font-size:14px;cursor:pointer}
.toggle input{width:18px;height:18px;min-height:0;accent-color:var(--accent)}
.badge{display:inline-block;font-size:12px;line-height:20px;padding:0 8px;border-radius:999px;background:var(--surface-2);color:var(--muted);border:1px solid var(--line);white-space:nowrap}
.badge.ok{background:var(--ok-soft);color:var(--ok);border-color:transparent}
.badge.bad{background:var(--bad-soft);color:var(--bad);border-color:transparent}
.badge.warn{background:var(--warn-soft);color:var(--warn);border-color:transparent}
.badge.info{background:var(--accent-soft);color:var(--accent);border-color:transparent}
table{width:100%;border-collapse:collapse}
th{font-size:12px;font-weight:500;color:var(--muted);text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);white-space:nowrap}
td{padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:0}
.r{text-align:right}
.name{font-weight:500;color:var(--ink);word-break:break-word}
.url{font-size:12px;color:var(--muted);word-break:break-all}
.msg{padding:10px 12px;border-radius:var(--r-s);font-size:14px;margin:12px 0 0}
.msg.error{background:var(--bad-soft);color:var(--bad)}
.msg.okay{background:var(--ok-soft);color:var(--ok)}
.preview{margin-top:16px;border:1px solid var(--line);border-radius:var(--r-m);overflow:hidden}
.preview-head{padding:14px 16px;background:var(--surface-2);display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.preview-body{padding:6px 16px 16px}
.plist{list-style:none;margin:0;padding:0}
.plist li{display:flex;gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid var(--line)}
.plist li:last-child{border-bottom:0}
.plist img{width:40px;height:40px;object-fit:cover;border-radius:var(--r-s);background:var(--surface-2);flex:none}
.plist .p{margin-left:auto;text-align:right;white-space:nowrap}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0}
.stat{background:var(--surface);border-radius:var(--r-m);box-shadow:var(--shadow);padding:14px 16px}
.stat b{display:block;font-family:"Instrument Serif",Georgia,serif;font-weight:400;font-size:30px;line-height:1.1;color:var(--ink);letter-spacing:-.02em}
.stat span{font-size:13px;color:var(--muted)}
@media (max-width:560px){.stats{grid-template-columns:1fr}.hide-s{display:none}}
.empty{padding:28px 12px;text-align:center;color:var(--muted)}
.steps{margin:8px 0 0;padding-left:18px;color:var(--muted);font-size:13px}
.steps li{margin:2px 0}
.price-edit{display:flex;gap:6px;align-items:center;justify-content:flex-end}
.price-edit input{width:96px;min-height:36px;padding:6px 8px;text-align:right}
.icon-btn{min-height:36px;min-width:44px;padding:0 10px}
.center{min-height:70vh;display:grid;place-items:center;text-align:center}
.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--ink);color:var(--surface);padding:10px 16px;border-radius:var(--r-s);font-size:14px;opacity:0;transition:opacity .2s;pointer-events:none;max-width:90vw}
.toast.show{opacity:1}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.img-ph{width:40px;height:40px;border-radius:var(--r-s);background:var(--surface-2);flex:none}
</style>
</head>
<body>
<header class="top"><div class="wrap">
  <div class="brand"><i>D</i>Denoro <small>Monitor de precios</small></div>
  <div class="spacer"></div>
  <span class="hint" id="last"></span>
  <button id="checkNow" type="button">Revisar ahora</button>
</div></header>

<main class="wrap" id="app">
  <div class="center" id="loading"><p class="hint">Cargando tu panel…</p></div>
</main>
<div class="toast" id="toast" role="status" aria-live="polite"></div>

<template id="tpl">
  <h1 id="title"></h1>
  <p class="sub">Pega enlaces de tu competencia y te avisamos cuando cambien sus precios o su stock.</p>

  <div class="stats">
    <div class="stat"><b class="num" id="sLinks">0</b><span>enlaces vigilados</span></div>
    <div class="stat"><b class="num" id="sProducts">0</b><span>productos en seguimiento</span></div>
    <div class="stat"><b class="num" id="sChanges">0</b><span>cambios en la última revisión</span></div>
  </div>

  <div class="grid">
    <section>
      <div class="card">
        <div class="card-head"><h2>Añadir un enlace</h2><span class="hint" id="quota"></span></div>
        <form id="addForm" class="add" autocomplete="off">
          <label for="url" class="sr-only">Enlace de la tienda o del producto</label>
          <input id="url" name="url" inputmode="url" placeholder="https://tienda-competidor.com/products/camiseta" required>
          <button class="primary" id="detectBtn" type="submit">Comprobar</button>
        </form>
        <ul class="steps">
          <li><b>Producto concreto</b> (cualquier tienda): vigilamos su precio y stock. Puedes indicar tu precio para saber si te ganan.</li>
          <li><b>Tienda entera</b> (Shopify o WooCommerce): pega la página principal o una colección y vigilamos todo su catálogo.</li>
        </ul>
        <div id="addMsg"></div>
        <div id="preview"></div>
      </div>

      <div class="card">
        <div class="card-head"><h2>Lo que estás vigilando</h2><span class="hint">Se revisa automáticamente</span></div>
        <div style="overflow-x:auto"><table>
          <thead><tr><th>Enlace</th><th class="hide-s">Estado</th><th class="r">Precio actual</th><th class="r">Tu precio</th><th></th></tr></thead>
          <tbody id="watchRows"></tbody>
        </table></div>
      </div>
    </section>

    <aside>
      <div class="card">
        <h2>Dónde te avisamos</h2>
        <p class="hint" style="margin:0 0 14px">Un único resumen cuando hay cambios. Nunca spam.</p>
        <form id="settingsForm">
          <div class="field"><label for="email">Email</label><input id="email" type="email" placeholder="tu@tienda.com"></div>
          <div class="field"><label for="chat">Telegram · chat ID</label><input id="chat" inputmode="numeric" placeholder="123456789">
            <ol class="steps"><li>Abre <a id="botLink" href="#" target="_blank" rel="noopener">el bot de avisos</a> y pulsa <b>Iniciar</b>.</li><li>Escribe a <a href="https://t.me/userinfobot" target="_blank" rel="noopener">@userinfobot</a> y copia tu <b>Id</b>.</li></ol></div>
          <div class="field"><label for="freq">Revisar cada</label>
            <select id="freq"><option value="1">1 hora</option><option value="3">3 horas</option><option value="6">6 horas</option><option value="12">12 horas</option><option value="24">24 horas</option></select></div>
          <div class="field"><label for="thr">Avisar a partir de un cambio del</label>
            <select id="thr"><option value="0">cualquier cambio</option><option value="1">1 %</option><option value="3">3 %</option><option value="5">5 %</option><option value="10">10 %</option></select></div>
          <label class="toggle"><input type="checkbox" id="optStock"> Cambios de stock</label>
          <label class="toggle"><input type="checkbox" id="optNew"> Productos nuevos</label>
          <label class="toggle"><input type="checkbox" id="optRemoved"> Productos retirados</label>
          <div class="row" style="margin-top:14px"><button class="primary" type="submit" id="saveSettings">Guardar</button><button type="button" id="testBtn">Enviar prueba</button></div>
          <div id="setMsg"></div>
        </form>
      </div>
    </aside>
  </div>
</template>

<script>
(() => {
  const API = location.pathname.replace(/\/panel\/?$/, '/api');
  const BOT = '__BOT_USERNAME__';
  const token = new URLSearchParams(location.search).get('t') || '';
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const TYPES = { shopify_tienda: 'Tienda Shopify', woo_tienda: 'Tienda WooCommerce', shopify_producto: 'Producto · Shopify', woo_producto: 'Producto · WooCommerce', producto: 'Producto' };
  const fmtMoney = (v, cur) => v === null || v === undefined ? '—' : new Intl.NumberFormat('es-ES', cur ? { style: 'currency', currency: cur } : { minimumFractionDigits: 2 }).format(v);
  const ago = (iso) => {
    if (!iso) return 'pendiente';
    const m = Math.round((Date.now() - new Date(iso)) / 60000);
    if (m < 1) return 'hace un momento'; if (m < 60) return `hace ${m} min`;
    const h = Math.round(m / 60); if (h < 24) return `hace ${h} h`;
    return new Date(iso).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
  };
  let state = null;
  let pending = null;

  function toast(t) { const el = $('toast'); el.textContent = t; el.classList.add('show'); clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove('show'), 3200); }
  function msg(id, text, kind = 'error') { $(id).innerHTML = text ? `<p class="msg ${kind}">${esc(text)}</p>` : ''; }
  async function api(accion, data = {}) {
    let res;
    try { res = await fetch(API, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ token, accion, ...data }) }); }
    catch (e) { return { ok: false, error: 'No hay conexión con el servidor. Inténtalo en un momento.' }; }
    try { return await res.json(); } catch (e) { return { ok: false, error: `Error del servidor (${res.status})` }; }
  }
  async function busy(btn, fn) { const t = btn.textContent; btn.disabled = true; btn.textContent = '…'; try { return await fn(); } finally { btn.disabled = false; btn.textContent = t; } }

  function render() {
    const s = state;
    $('title').textContent = s.cliente.nombre;
    const watches = s.vigilancias;
    $('sLinks').textContent = watches.length;
    $('sProducts').textContent = watches.reduce((a, w) => a + (w.estado?.productos || 0), 0).toLocaleString('es-ES');
    $('sChanges').textContent = s.resumen?.cambios ?? '—';
    $('last').textContent = s.resumen?.ultima ? `Última revisión ${ago(s.resumen.ultima)}` : 'Aún sin revisar';
    $('quota').textContent = `${watches.length} de ${s.ajustes.max_vigilancias} enlaces`;
    const rows = watches.map((w) => {
      const e = w.estado;
      const beaten = e && w.mi_precio && e.precio !== null && e.precio !== undefined && e.precio < w.mi_precio * (1 - (w.tolerancia_pct || 0) / 100);
      const badge = !e ? '<span class="badge info">Pendiente</span>'
        : e.error && e.fallos ? `<span class="badge bad" title="${esc(e.error)}">Error</span>`
        : e.retirado ? '<span class="badge warn">No disponible</span>'
        : beaten ? `<span class="badge bad">Te gana ${Math.abs(Math.round((e.precio - w.mi_precio) / w.mi_precio * 1000) / 10).toLocaleString('es-ES')} %</span>`
        : `<span class="badge ok">${e.productos > 1 ? e.productos.toLocaleString('es-ES') + ' productos' : 'OK'}</span>`;
      const isStore = /tienda$/.test(w.tipo);
      const price = isStore ? '<span class="hint">catálogo</span>' : e ? `<span class="num"${beaten ? ' style="color:var(--bad);font-weight:600"' : ''}>${fmtMoney(e.precio, e.moneda || w.moneda)}</span>${e.stock === false ? '<div class="url">sin stock</div>' : ''}` : '—';
      const mine = isStore ? '<span class="hint">—</span>'
        : `<form class="price-edit" data-id="${esc(w.id)}"><input aria-label="Tu precio" inputmode="decimal" name="p" value="${w.mi_precio ?? ''}" placeholder="—"><button class="icon-btn" type="submit" title="Guardar tu precio">OK</button></form>`;
      return `<tr><td><div class="name">${esc(w.nombre)}</div><div class="url">${esc(TYPES[w.tipo] || w.tipo)} · <a href="${esc(w.url)}" target="_blank" rel="noopener">${esc(w.url.replace(/^https?:\/\//, '').slice(0, 60))}</a></div>
        <div class="url">${e ? 'Revisado ' + ago(e.ultima) : 'Se revisará en la próxima pasada'}</div></td>
        <td class="hide-s">${badge}</td><td class="r">${price}</td><td class="r">${mine}</td>
        <td class="r"><button class="ghost danger icon-btn" data-del="${esc(w.id)}" title="Dejar de vigilar" aria-label="Dejar de vigilar ${esc(w.nombre)}">✕</button></td></tr>`;
    }).join('');
    $('watchRows').innerHTML = rows || '<tr><td colspan="5" class="empty">Todavía no vigilas nada. Pega arriba el enlace de un producto o de una tienda.</td></tr>';
    $('email').value = s.cliente.email; $('chat').value = s.cliente.telegram_chat_id;
    $('freq').value = String(s.ajustes.frecuencia_horas); $('thr').value = String(s.ajustes.umbral_pct);
    if (!$('thr').value) { $('thr').insertAdjacentHTML('beforeend', `<option value="${s.ajustes.umbral_pct}">${s.ajustes.umbral_pct} %</option>`); $('thr').value = String(s.ajustes.umbral_pct); }
    $('optStock').checked = s.ajustes.avisar_stock; $('optNew').checked = s.ajustes.avisar_nuevos; $('optRemoved').checked = s.ajustes.avisar_retirados;
  }

  function renderPreview(d) {
    const isStore = /tienda$/.test(d.tipo);
    const items = (d.productos || []).map((p) => `<li>${p.image ? `<img src="${esc(p.image)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.visibility='hidden'">` : '<span class="img-ph"></span>'}
      <div><div class="name">${esc(p.name)}</div>${p.stock === false ? '<div class="url">sin stock</div>' : ''}</div>
      <div class="p"><span class="num">${fmtMoney(p.price, p.currency || d.moneda)}</span>${p.regular ? `<div class="url"><s>${fmtMoney(p.regular, p.currency || d.moneda)}</s></div>` : ''}</div></li>`).join('');
    $('preview').innerHTML = `<div class="preview"><div class="preview-head"><span class="badge info">${esc(TYPES[d.tipo] || d.tipo)}</span>
      <div><div class="name">${esc(d.nombre)}</div><div class="url">${isStore ? `${esc(String(d.total))} productos encontrados` : 'Producto encontrado'}</div></div></div>
      <div class="preview-body">${d.aviso ? `<p class="msg" style="background:var(--warn-soft);color:var(--warn)">${esc(d.aviso)}</p>` : ''}<ul class="plist">${items}</ul>
      <form id="confirmForm" style="margin-top:14px">
        <div class="row">
          <div><label for="wName">Nombre para reconocerlo</label><input id="wName" value="${esc(d.nombre)}" maxlength="80"></div>
          ${isStore ? '' : `<div><label for="wMine">Tu precio (opcional)</label><input id="wMine" inputmode="decimal" placeholder="Ej. 24,90"></div>
          <div><label for="wTol">Margen</label><select id="wTol"><option value="0">Avisar si es más barato</option><option value="2">…más de un 2 %</option><option value="5">…más de un 5 %</option></select></div>`}
        </div>
        <div class="row" style="margin-top:4px"><button class="primary" type="submit" id="saveWatch">Empezar a vigilar</button><button type="button" id="cancelWatch">Cancelar</button></div>
      </form></div></div>`;
    $('confirmForm').addEventListener('submit', async (ev) => {
      ev.preventDefault();
      await busy($('saveWatch'), async () => {
        const r = await api('guardar_vigilancia', { url: pending.url, nombre: $('wName').value, mi_precio: $('wMine')?.value ?? '', tolerancia_pct: $('wTol')?.value ?? 0 });
        if (!r.ok) return msg('addMsg', r.error);
        $('preview').innerHTML = ''; $('url').value = ''; pending = null;
        msg('addMsg', r.mensaje || 'Guardado', 'okay');
        await load();
      });
    });
    $('cancelWatch').addEventListener('click', () => { $('preview').innerHTML = ''; pending = null; });
  }

  async function load() {
    const r = await api('estado');
    if (!r.ok) { $('app').innerHTML = `<div class="center"><div><h1>No podemos abrir tu panel</h1><p class="sub">${esc(r.error)}</p></div></div>`; $('checkNow').hidden = true; return; }
    const first = !state; state = r;
    if (first) {
      $('app').innerHTML = ''; $('app').append($('tpl').content.cloneNode(true)); bind();
      if (BOT && !BOT.startsWith('__')) $('botLink').href = `https://t.me/${BOT}`; else $('botLink').removeAttribute('href');
    }
    render();
  }

  function bind() {
    $('addForm').addEventListener('submit', async (ev) => {
      ev.preventDefault(); msg('addMsg', ''); $('preview').innerHTML = '';
      await busy($('detectBtn'), async () => {
        const r = await api('detectar', { url: $('url').value });
        if (!r.ok) return msg('addMsg', r.error);
        pending = r; renderPreview(r);
      });
    });
    $('watchRows').addEventListener('click', async (ev) => {
      const id = ev.target.closest('[data-del]')?.dataset.del; if (!id) return;
      const w = state.vigilancias.find((x) => x.id === id);
      if (!confirm(`¿Dejar de vigilar «${w.nombre}»?`)) return;
      const r = await api('borrar_vigilancia', { id }); if (!r.ok) return toast(r.error);
      toast('Enlace eliminado'); load();
    });
    $('watchRows').addEventListener('submit', async (ev) => {
      ev.preventDefault(); const f = ev.target.closest('form'); if (!f) return;
      const r = await api('editar_vigilancia', { id: f.dataset.id, mi_precio: f.p.value });
      toast(r.ok ? 'Precio guardado' : r.error); if (r.ok) load();
    });
    $('settingsForm').addEventListener('submit', async (ev) => {
      ev.preventDefault(); msg('setMsg', '');
      await busy($('saveSettings'), async () => {
        const r = await api('ajustes', { email: $('email').value, telegram_chat_id: $('chat').value, frecuencia_horas: +$('freq').value, umbral_pct: +$('thr').value,
          avisar_stock: $('optStock').checked, avisar_nuevos: $('optNew').checked, avisar_retirados: $('optRemoved').checked });
        if (!r.ok) return msg('setMsg', r.error);
        msg('setMsg', 'Ajustes guardados', 'okay'); load();
      });
    });
    $('testBtn').addEventListener('click', async () => {
      msg('setMsg', '');
      await busy($('testBtn'), async () => {
        const r = await api('probar_aviso');
        msg('setMsg', r.ok ? r.mensaje : r.error, r.ok ? 'okay' : 'error');
      });
    });
  }

  $('checkNow').addEventListener('click', async () => {
    await busy($('checkNow'), async () => {
